enum FeedFailure { case transient, unauthorized, invalidData }
func retryDelay(_ failure: FeedFailure, attempt: Int) -> Int? {
    guard case .transient = failure, (1...2).contains(attempt) else {
        return nil
    }
    return [1, 2][attempt - 1]
}
assert(retryDelay(.transient, attempt: 1) == 1)
assert(retryDelay(.transient, attempt: 2) == 2)
assert(retryDelay(.transient, attempt: 3) == nil)
assert(retryDelay(.unauthorized, attempt: 1) == nil)
assert(retryDelay(.invalidData, attempt: 1) == nil)
assert(retryDelay(.transient, attempt: 0) == nil)

Лимит относится к числу попыток, а не к бесконечной смене задержки. Постоянную ошибку нужно разобрать или восстановить доступ, не повторять этим правилом.

struct RefreshToken { let generation: Int }
struct RefreshGate {
    private(set) var generation = 0
    private(set) var rows: [Int] = []
    mutating func refresh() -> RefreshToken {
        generation += 1
        return RefreshToken(generation: generation)
    }
    mutating func accept(_ ids: [Int], token: RefreshToken) {
        guard token.generation == generation else { return }
        rows = ids
    }
}
var gate = RefreshGate()
let old = gate.refresh()
let latest = gate.refresh()
gate.accept([31], token: old)
assert(gate.rows.isEmpty)
gate.accept([32, 33], token: latest)
assert(gate.rows == [32, 33])
gate.accept([31], token: old)
assert(gate.rows == [32, 33])

Проверка выполняется до изменения результата; отмена запроса не заменяет контроль generation. Это детерминированная модель ответов, не настоящая сеть.

struct Post: Equatable {
    let id: Int
    let revision: Int
    let order: Int
    let title: String
    let isSaved: Bool
}
struct CachedPost: Equatable {
    var server: Post
    var pendingSaved: Bool?
    var visibleSaved: Bool { pendingSaved ?? server.isSaved }
}
func applyDeleted(_ ids: Set<Int>, local: [CachedPost]) -> [CachedPost] {
    local.filter { !ids.contains($0.server.id) }
}
let a = Post(id: 31, revision: 1, order: 10,
             title: "Пост", isSaved: false)
let b = Post(id: 32, revision: 1, order: 9,
             title: "Другой", isSaved: false)
let local = [CachedPost(server: a, pendingSaved: true),
             CachedPost(server: b, pendingSaved: nil)]
let result = applyDeleted([31], local: local)
assert(result.map { $0.server.id } == [32])
assert(applyDeleted([], local: local) == local)
assert(applyDeleted([99], local: local) == local)

Новая механика — явное удаление, не ещё одно обновление revision. Локальная закладка не воскрешает удалённый сервером пост по выбранному контракту.
